-- Created: 2026-08-09

-- Addressable session identity (#3318).
--
-- sessions.pid has been unusable since 001. The registrar wrote process.pid,
-- which under CC is the `node run-hook.mjs` CHILD — a process that has already
-- exited by the time any reader looks at the row. Every peer warning printed
-- since #2242 named a dead pid.
--
-- Two columns now carry identity instead of one derived guess:
--   pid              — the Claude Code process itself, from CLAUDE_PID. 0 when
--                      CC exports none (honest "unknown", never a live-looking
--                      pid belonging to something else).
--   messaging_socket — the peer-messaging socket CC exports as
--                      CLAUDE_CODE_MESSAGING_SOCKET, stored VERBATIM. Never
--                      re-derived from a pid: the /tmp/cc-socks/<pid>.sock
--                      shape is CC's business, not ours, and re-deriving it
--                      would rebuild the same guess this migration removes.
--
-- messaging_socket IS NULL is the exact predicate separating a peer you can
-- reach over the socket from one you must reach another way.

PRAGMA user_version = 4;

ALTER TABLE sessions ADD COLUMN messaging_socket TEXT;
